package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaKnDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("ಎಲ್ಲಾ ಹಾನಿಗಳಿಂದ ರಕ್ಷಣೆ", "ಅಲ್ಲಾಹನ ಹೆಸರಿನಲ್ಲಿ, ಅವನ ಹೆಸರಿನಲ್ಲಿ ಭೂಮಿಯ ಮೇಲಾಗಲಿ ಅಥವಾ ಆಕಾಶದಲ್ಲಾಗಲಿ ಯಾವುದೂ ಹಾನಿ ಮಾಡಲಾರದು, ಮತ್ತು ಅವನು ಎಲ್ಲವನ್ನೂ ಕೇಳುವವನು, ಎಲ್ಲವನ್ನೂ ಬಲ್ಲವನು.", "ಪ್ರತಿ ದಿನ ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ ಮೂರು ಬಾರಿ.", "ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ ಮೂರು ಬಾರಿ ಇದನ್ನು ಹೇಳಿದವನು, ಅವನಿಗೆ ಏನೂ ಹಾನಿಯಾಗುವುದಿಲ್ಲ."),
        "dua_raditu_billahi" to DuaText("ಅಲ್ಲಾಹನನ್ನು ಭಗವಂತನನ್ನಾಗಿ ಸ್ವೀಕರಿಸಿ", "ನನ್ನ ಪ್ರಭುವಾಗಿ ಅಲ್ಲಾಹನಿಗೂ, ಇಸ್ಲಾಂ ಧರ್ಮವನ್ನು ನನ್ನ ಧರ್ಮವಾಗಿ ಮತ್ತು ಮುಹಮ್ಮದ್ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರನ್ನು ನನ್ನ ಪ್ರವಾದಿ ಎಂದು ನಾನು ಮೆಚ್ಚುತ್ತೇನೆ.", "ಮೂರು ಬಾರಿ ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ.", "ತೀರ್ಪಿನ ದಿನದಂದು ಅವನನ್ನು ಮೆಚ್ಚಿಸುವ ಹಕ್ಕು ಅಲ್ಲಾಹನಿಗೆ ಇದೆ."),
        "dua_hasbiyallah" to DuaText("ಹಸ್ಬಿಯಲ್ಲಾ (ಅಲ್ಲಾಹ್ ಸಾಕಷ್ಟಿದೆ)", "ನನಗೆ ಅಲ್ಲಾಹ್ ಸಾಕಾಗಿದ್ದಾನೆ. ಅವನ ಹೊರತು ಬೇರೆ ದೇವರು ಇಲ್ಲ. ನಾನು ಅವನ ಮೇಲೆ ಭರವಸೆ ಇಟ್ಟಿದ್ದೇನೆ ಮತ್ತು ಅವನು ಪರಾಕ್ರಮಶಾಲಿ ಸಿಂಹಾಸನದ ಒಡೆಯನಾಗಿದ್ದಾನೆ.", "ಏಳು ಬಾರಿ ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ.", "ಕುರಾನ್ನ ಒಂದು ಶ್ಲೋಕಃ ಈ ಲೋಕ ಮತ್ತು ಪರಕಾಲದ ಚಿಂತೆಗಳ ವಿರುದ್ಧ ಅಲ್ಲಾಹ್ ಸಾಕು."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("ಸುಭಾನ್ ಅಲ್ಲಾಹಿ ವಾ ಬಿಹಮ್ದಿಹಿ", "ಅಲ್ಲಾಹನಿಗೆ ಮಹಿಮೆ ಇರಲಿ ಮತ್ತು ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಅವನದೇ.", "ದಿನಕ್ಕೆ ನೂರು ಬಾರಿ.", "ದಿನಕ್ಕೆ ನೂರು ಬಾರಿ ಇದನ್ನು ಹೇಳುವವರ ಪಾಪಗಳು ಸಮುದ್ರದ ಫೋಮ್ನಂತೆ ಇದ್ದರೂ ಸಹ, ಅವರು ಕ್ಷಮಿಸಲ್ಪಡುತ್ತಾರೆ."),
        "dua_tahleel_100" to DuaText("ಲಾ ಇಲಾಹಾ ಇಲ್ಲಲ್ಲಾಹು ವಾಹ್ದಾಹು", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ, ಒಬ್ಬನೇ, ಪಾಲುದಾರನಿಲ್ಲದೆ ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ. ಪ್ರಭುತ್ವವು ಅವನಿಗೇ ಸೇರಿದ್ದು, ಸ್ತುತಿಯೂ ಅವನಿಗೇ ಸೇರಿದ್ದು, ಅವನು ಎಲ್ಲ ವಸ್ತುಗಳ ಮೇಲೆ ಪ್ರಭುತ್ವವನ್ನು ಹೊಂದಿದ್ದಾನೆ.", "ಇದನ್ನು ದಿನಕ್ಕೆ ನೂರು ಬಾರಿ ಹೇಳುವುದು ದೊಡ್ಡ ಪುಣ್ಯ.", "ಹತ್ತು ಗುಲಾಮರನ್ನು ಬಿಡುಗಡೆ ಮಾಡುವ ಪ್ರತಿಫಲ, ಬರೆದ ನೂರು ಒಳ್ಳೆಯ ಕಾರ್ಯಗಳು, ನೂರು ಪಾಪಗಳು ಅಳಿಸಿಹೋಗಿವೆ ಮತ್ತು ಸಂಜೆಯವರೆಗೆ ಸೈತಾನ್ನಿಂದ ರಕ್ಷಣೆ."),
        "dua_leaving_mosque" to DuaText("ಮಸೀದಿಯಿಂದ ಹೊರಹೋಗುವುದು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನ ಅನುಗ್ರಹವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಎಡಗೈಯೊಂದಿಗೆ ಮಸೀದಿಯಿಂದ ಹೊರಬರುವಾಗ.", "ಮಸೀದಿಯಿಂದ ಹೊರಡುವಾಗ ಅಲ್ಲಾಹನ ಅನುಗ್ರಹ ಮತ್ತು ಪೋಷಣೆಯನ್ನು ಕೇಳಿಕೊಳ್ಳುವುದು."),
        "dua_after_adhan" to DuaText("ಅದಾನ್ ನಂತರ", "ಓ ಅಲ್ಲಾಹನೇ, ಈ ಪರಿಪೂರ್ಣ ಕರೆ ಮತ್ತು ಸ್ಥಾಪನೆಯಾಗಲಿರುವ ಪ್ರಾರ್ಥನೆಯ ಒಡೆಯನೇ, ಮುಹಮ್ಮದ್ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಿಲಾ ಮತ್ತು ಸದ್ಗುಣವನ್ನು ನೀಡಿ, ಮತ್ತು ನೀನು ಅವನಿಗೆ ವಾಗ್ದಾನ ಮಾಡಿದ ಸ್ತುತ್ಯಾರ್ಹ ಸ್ಥಳಕ್ಕೆ ಅವನನ್ನು ಏರಿಸು.", "ಅದಾನ್ ಮುಗಿದ ನಂತರ.", "ಇದನ್ನು ಹೇಳುವವರಿಗೆ ತೀರ್ಪಿನ ದಿನದಂದು ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರ ಮಧ್ಯಸ್ಥಿಕೆಯನ್ನು ನೀಡಲಾಗುತ್ತದೆ."),
        "dua_after_salah_istighfar" to DuaText("ಫರ್ದ್ ಸಲಾಹ್ ನಂತರ", "ನಾನು ಅಲ್ಲಾಹನಿಂದ ಕ್ಷಮೆ ಕೋರುತ್ತೇನೆ (3 ಬಾರಿ). ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ಸಲಾಂ ಆಗಿದ್ದೀ ಮತ್ತು ನಿನ್ನಿಂದ ಶಾಂತಿ ಇದೆ. ಓ ಘನತೆ ಮತ್ತು ಗೌರವದ ಒಡೆಯನೇ, ನೀನು ಧನ್ಯಳು.", "ಸಲಾಂ ಮುಗಿದ ತಕ್ಷಣ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಪ್ರತಿ ಕಡ್ಡಾಯ ಪ್ರಾರ್ಥನೆಯ ನಂತರ ಇದನ್ನು ಪಠಿಸಿದರು."),
        "dua_after_salah_help_dhikr" to DuaText("ನಿನ್ನನ್ನು ನೆನಪಿಸಿಕೊಳ್ಳಲು ನನಗೆ ಸಹಾಯ ಮಾಡು.", "ಓ ಅಲ್ಲಾಹನೇ, ನಿನ್ನನ್ನು ಸ್ಮರಿಸಲು, ಧನ್ಯವಾದ ಹೇಳಲು ಮತ್ತು ಅತ್ಯುತ್ತಮ ರೀತಿಯಲ್ಲಿ ನಿನ್ನನ್ನು ಆರಾಧಿಸಲು ನನಗೆ ಸಹಾಯ ಮಾಡು.", "ಪ್ರತಿ ಪ್ರಾರ್ಥನೆಯ ನಂತರ-ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರು ಇದನ್ನು ಹೇಳಲು ಮು'ದ್ (ರ) ಗೆ ಸಲಹೆ ನೀಡಿದರು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರ ವಿಶೇಷ ಸಲಹೆ-ಆರಾಧನೆಯಲ್ಲಿ ಶ್ರೇಷ್ಠತೆ ಮತ್ತು ಸ್ಥಿರತೆ."),
        "dua_sleep_tasbeeh" to DuaText("ನಿದ್ರೆ ಮಾಡುವ ಮೊದಲು ತಸ್ಬೆಹ್-ಎ-ಫಾತಿಮಿ", "ಅಲ್ಲಾಹನಿಗೆ ಮಹಿಮೆ (33), ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಅಲ್ಲಾಹನಿಗೇ (33), ಅಲ್ಲಾಹನು ಶ್ರೇಷ್ಠ (34).", "ಮಲಗುವ ಮೊದಲು-ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಇದನ್ನು ಫಾತಿಮಾ ಮತ್ತು ಅಲಿ (ರ.) ಅವರಿಗೆ ಕಲಿಸಿದರು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು, ಇದು ಸೇವಕನಿಗಿಂತ ನಿಮಗೆ ಉತ್ತಮವಾಗಿದೆ ಎಂದು ಹೇಳಿದರು."),
        "dua_sleep_qina_adhab" to DuaText("ಶಿಕ್ಷೆಯಿಂದ ರಕ್ಷಣೆ", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ನಿನ್ನ ಸೇವಕರನ್ನು ಪುನರುತ್ಥಾನಗೊಳಿಸುವ ದಿನದಂದು ನಿನ್ನ ಶಿಕ್ಷೆಯಿಂದ ನನ್ನನ್ನು ರಕ್ಷಿಸು.", "ಮೂರು ಬಾರಿ, ಬಲಗೈಯನ್ನು ಕೆನ್ನೆಯ ಕೆಳಗೆ ಇರಿಸಿ.", "ನಿದ್ರೆಯು ಮರಣದ ಜ್ಞಾಪನೆ ಮತ್ತು ಪರಕಾಲಕ್ಕೆ ಸಿದ್ಧತೆಯಾಗಿ ಬದಲಾಗುತ್ತದೆ."),
        "dua_bad_dream" to DuaText("ಕೆಟ್ಟ ಕನಸಿನ ನಂತರ", "ನಾನು ಶಾಪಗ್ರಸ್ತರಾದ ಸೈತಾನ್ನಿಂದ ಅಲ್ಲಾಹನ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಕೆಟ್ಟ ಕನಸಿನ ನಂತರಃ ಎಡಕ್ಕೆ ಮೂರು ಬಾರಿ ಲಘುವಾಗಿ ಒಣಗಿಸಿ, ನಂತರ ಇನ್ನೊಂದು ಬದಿಯತ್ತ ತಿರುಗಿ.", "ಕೆಟ್ಟ ಕನಸು ನಿಮಗೆ ಹಾನಿಯನ್ನುಂಟು ಮಾಡುವುದಿಲ್ಲ; ಅದರ ಬಗ್ಗೆ ಯಾರಿಗೂ ಹೇಳಬೇಡಿ."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("ಯಾ ಹಯ್ಯೂ ಯಾ ಕಯುಮ್", "ಓ ಸರ್ವಜೀವಿಯೇ, ಎಲ್ಲರ ಪಾಲಕರೇ, ನಿನ್ನ ಕರುಣೆಯಿಂದ ನಾನು ಸಹಾಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಒಂದು ವಿಷಯವು ತುಂಬಾ ಭಾರವಾದಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರಿಗೆ ಏನಾದರೂ ತೊಂದರೆ ನೀಡಿದಾಗಲೆಲ್ಲಾ, ಅವರು ಇದನ್ನು ಹೇಳುತ್ತಿದ್ದರು."),
        "dua_entering_market" to DuaText("ಮಾರುಕಟ್ಟೆಯ ಪ್ರವೇಶ", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ, ಒಬ್ಬನೇ, ಸಂಗಾತಿಯಿಲ್ಲದ, ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ. ಪ್ರಭುತ್ವವು ಅವನಿಗೇ ಇದೆ ಮತ್ತು ಸ್ತುತಿಯೂ ಅವನಿಗೇ ಇದೆ. ಅವನು ಜೀವವನ್ನು ನೀಡುತ್ತಾನೆ ಮತ್ತು ಮರಣವನ್ನು ಉಂಟುಮಾಡುತ್ತಾನೆ, ಮತ್ತು ಅವನು ಶಾಶ್ವತನಾಗಿದ್ದಾನೆ ಮತ್ತು ಎಂದಿಗೂ ಸಾಯುವುದಿಲ್ಲ. ಅವನ ಕೈಯಲ್ಲಿ ಎಲ್ಲವೂ ಒಳ್ಳೆಯದು, ಮತ್ತು ಅವನು ಎಲ್ಲದರ ಮೇಲೆ ಅಧಿಕಾರವನ್ನು ಹೊಂದಿದ್ದಾನೆ.", "ಮಾರುಕಟ್ಟೆಯನ್ನು ಪ್ರವೇಶಿಸುವಾಗ.", "ಹದೀಸ್ ಅದಕ್ಕೆ ದೊಡ್ಡ ಬಹುಮಾನವನ್ನು (ಒಂದು ಮಿಲಿಯನ್ ಒಳ್ಳೆಯ ಕಾರ್ಯಗಳು) ಉಲ್ಲೇಖಿಸುತ್ತದೆ."),
        "dua_adam_forgiveness" to DuaText("ಪ್ರವಾದಿ ಆದಮ್ (ಅ. ಸ.) ಅವರ ದುವಾ", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಾವು ನಮ್ಮ ಮೇಲೆ ಅನ್ಯಾಯ ಮಾಡಿದ್ದೇವೆ. ಮತ್ತು ನೀನು ನಮ್ಮನ್ನು ಕ್ಷಮಿಸದಿದ್ದರೆ ಮತ್ತು ನಮ್ಮ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸದಿದ್ದರೆ, ನಾವು ಖಂಡಿತವಾಗಿಯೂ ನಷ್ಟಕ್ಕೊಳಗಾದವರಲ್ಲಿ ಸೇರುವೆವು.", "ಆದಮ್ ಮತ್ತು ಹವಾ (ಎ. ಎಸ್) ಅವರ ಪಶ್ಚಾತ್ತಾಪದ ದುಆ.", "ಮಾನವೀಯತೆಯ ಮೊದಲ ಪಶ್ಚಾತ್ತಾಪ-ಅಲ್ಲಾಹ್ ಅದನ್ನು ಸ್ವೀಕರಿಸಿದನು."),
        "dua_abu_bakr" to DuaText("ದುಆ ಅಬು ಬಕರ್ (ರ.) ಗೆ ಕಲಿಸಿದನು.", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನನ್ನ ಮೇಲೆ ಬಹಳ ಅನ್ಯಾಯ ಮಾಡಿದ್ದೇನೆ ಮತ್ತು ನಿನ್ನ ಹೊರತು ಬೇರೆ ಯಾರೂ ಪಾಪಗಳನ್ನು ಕ್ಷಮಿಸುವುದಿಲ್ಲ. ಆದ್ದರಿಂದ ನನಗೆ ನಿನ್ನ ಕಡೆಯಿಂದ ಕ್ಷಮೆ ಮಾಡು ಮತ್ತು ನನ್ನ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸು. ನಿಶ್ಚಯವಾಗಿ ನೀನು ಕ್ಷಮಾಶೀಲನೂ ಕರುಣೆಯುಳ್ಳವನೂ ಆಗಿದ್ದೀ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಅಬೂಬಕ್ರ್ ಅಸ್-ಸಿದ್ದಿಕ್ (ರ. ಅ.) ಅವರಿಗೆ ಪ್ರಾರ್ಥನೆಯಲ್ಲಿ (ತಾಶಹುದ್ ನಂತರ) ಹೇಳುವುದನ್ನು ಕಲಿಸಿದರು.", "ಪ್ರಾರ್ಥನೆಯ ಅಂತ್ಯಕ್ಕೆ ಒಂದು ಸುನ್ನತ್ ದುಆ."),
        "dua_astaghfirullah_atubu" to DuaText("ದಿನಪತ್ರಿಕೆ ಇಸ್ತಿಘಫರ್", "ನಾನು ಅಲ್ಲಾಹನಿಂದ ಕ್ಷಮೆ ಕೋರುತ್ತೇನೆ ಮತ್ತು ಪಶ್ಚಾತ್ತಾಪದಿಂದ ಅವನ ಕಡೆಗೆ ತಿರುಗುತ್ತೇನೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ದಿನಕ್ಕೆ ಎಪ್ಪತ್ತು ಬಾರಿ ಕ್ಷಮೆ ಕೋರಿದರು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಹೇಳಿದರುಃ ನಾನು ಅಲ್ಲಾಹನಿಂದ ಕ್ಷಮೆ ಕೋರುತ್ತೇನೆ ಮತ್ತು ದಿನಕ್ಕೆ ಎಪ್ಪತ್ತು ಬಾರಿ ಅವನನ್ನು ಪಶ್ಚಾತ್ತಾಪಪಡುತ್ತೇನೆ."),
        "dua_laylatul_qadr" to DuaText("ಲೈಲತ್ ಅಲ್-ಖಾದರ್ಗೆ ದುವಾ", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ಅತ್ಯಂತ ಕ್ಷಮಿಸುವವನಾಗಿದ್ದೀ ಮತ್ತು ಕ್ಷಮಿಸಲು ಇಷ್ಟಪಡುವವನಾಗಿದ್ದೀ, ಆದ್ದರಿಂದ ನನ್ನನ್ನು ಕ್ಷಮಿಸು.", "ಲೈಲತ್ ಅಲ್-ಖಾದರ್ಗಾಗಿ ಆಯಿಶಾ (ಆರ್. ಎ.) ಗೆ ಕಲಿಸಲಾಯಿತು.", "ರಂಜಾನ್ ಮತ್ತು ಲೈಲತ್ ಅಲ್-ಖಾದರ್ನ ಕೊನೆಯ ರಾತ್ರಿಗಳಿಗೆ ವಿಶೇಷ ದುಆ."),
        "dua_family_coolness" to DuaText("ಕಣ್ಣುಗಳ ಶೀತಲತೆ (ಸಂಗಾತಿ ಮತ್ತು ಮಕ್ಕಳು)", "ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮ ಸಂಗಾತಿಗಳಿಂದ ಮತ್ತು ನಮ್ಮ ಸಂತತಿಗಳಿಂದ ನಮಗೆ ನಮ್ಮ ಕಣ್ಣುಗಳ ತಂಪನ್ನು ಕರುಣಿಸು ಮತ್ತು ನಮ್ಮನ್ನು ನೀತಿವಂತರ ನಾಯಕರನ್ನಾಗಿ ಮಾಡು.", "ಧಾರ್ಮಿಕ ಸಂಗಾತಿ ಮತ್ತು ಮಕ್ಕಳಿಗೆ ಕುರಾನ್ ದುಆ.", "ಮನೆಯಲ್ಲಿ ಶಾಂತಿ ಮತ್ತು ನೀತಿವಂತ ಮಕ್ಕಳಿಗಾಗಿ."),
        "dua_righteous_children" to DuaText("ನೀತಿವಂತ ಸಂತತಿಗಾಗಿ", "ನನ್ನ ಒಡೆಯನೇ, ನನಗೆ ನಿನ್ನ ಕಡೆಯಿಂದಲೇ ಶುದ್ಧ ಸಂತತಿಯನ್ನು ಕರುಣಿಸು. ನಿಶ್ಚಯವಾಗಿ ನೀನು ಪ್ರಾರ್ಥನೆಯನ್ನು ಕೇಳುವವನಾಗಿದ್ದೀ.", "ಪ್ರವಾದಿ ಜಕಾರಿಯಾ (ಅ. ಸ.) ಅವರ ದೂ.", "ಮಕ್ಕಳನ್ನು ಬಯಸುವವರಿಗೆ ಕುರಾನ್ ದುಆ."),
        "dua_ibrahim_prayer_family" to DuaText("ಪ್ರಾರ್ಥನೆಯ ಸ್ಥಾಪಕರು", "ನನ್ನ ಒಡೆಯನೇ, ನನ್ನನ್ನು ಪ್ರಾರ್ಥನೆಯನ್ನು ಸ್ಥಾಪಿಸುವವನಾಗಿ ಮತ್ತು ನನ್ನ ಸಂತತಿಯವನಾಗಿ ಮಾಡಿ. ನನ್ನ ಒಡೆಯನೇ, ನನ್ನ ಪ್ರಾರ್ಥನೆಯನ್ನು ಸ್ವೀಕರಿಸು. ನನ್ನ ಒಡೆಯನೇ, ಲೆಕ್ಕವು ಸಿದ್ಧವಾಗುವ ದಿನದಂದು ನನ್ನನ್ನೂ ನನ್ನ ತಂದೆತಾಯಿಗಳನ್ನೂ ಮತ್ತು ವಿಶ್ವಾಸಿಗಳನ್ನೂ ಕ್ಷಮಿಸು.", "ಪ್ರವಾದಿ ಇಬ್ರಾಹಿಂ (ಅ. ಸ.) ಅವರ ದುಆ ಸ್ವತಃ ಮತ್ತು ಅವರ ವಂಶಸ್ಥರಿಗೆ.", "ಸಾಮಾನ್ಯವಾಗಿ ಪ್ರಾರ್ಥನೆಯ ಕೊನೆಯಲ್ಲಿ ಪಠಿಸಲಾಗುತ್ತದೆ."),
        "dua_newlywed" to DuaText("ನವವಿವಾಹಿತರಿಗೆ ಶುಭಾಶಯಗಳು", "ಅಲ್ಲಾಹ್ ನಿಮ್ಮನ್ನು ಆಶೀರ್ವದಿಸಲಿ, ನಿಮ್ಮ ಮೇಲೆ ಆಶೀರ್ವಾದಗಳನ್ನು ಕಳುಹಿಸಲಿ ಮತ್ತು ನಿಮ್ಮಿಬ್ಬರನ್ನು ಒಳ್ಳೆಯತನದಲ್ಲಿ ಒಗ್ಗೂಡಿಸಲಿ.", "ಯಾರನ್ನಾದರೂ ಅವರ ಮದುವೆಗೆ ಅಭಿನಂದಿಸುವಾಗ.", "ಮದುವೆಗೆ ಸುನ್ನಹ್ ಶುಭಾಶಯಗಳು."),
        "dua_before_eating" to DuaText("ಊಟ ಮಾಡುವ ಮೊದಲು", "ಅಲ್ಲಾಹನ ಹೆಸರಿನಲ್ಲಿ. (ಮರೆತಿದ್ದರೆಃ) ಅಲ್ಲಾಹನ ಹೆಸರಿನಲ್ಲಿ, ಅದರ ಆರಂಭದಲ್ಲಿ ಮತ್ತು ಕೊನೆಯಲ್ಲಿ.", "ಊಟ ಮಾಡುವ ಮೊದಲು. ನೀವು ಮರೆತಿದ್ದರೆ, ಅದನ್ನು ಭಾಗಶಃ ಹೇಳಿ.", "ಬಿಸ್ಮಿಲ್ಲಾಹ್ ಹೇಳುವುದರಿಂದ ಸೈತಾನನು ಆಹಾರವನ್ನು ಹಂಚಿಕೊಳ್ಳದಂತೆ ತಡೆಯುತ್ತದೆ."),
        "dua_after_eating" to DuaText("ಊಟದ ನಂತರ", "ನನಗೆ ಇದನ್ನು ಪೋಷಿಸಿದ ಮತ್ತು ನನ್ನ ಕಡೆಯಿಂದ ಯಾವುದೇ ಶಕ್ತಿ ಅಥವಾ ಶಕ್ತಿಯಿಲ್ಲದೆ ನನಗೆ ಅದನ್ನು ಒದಗಿಸಿದ ಅಲ್ಲಾಹನಿಗಾಗಿ ಎಲ್ಲಾ ಪ್ರಶಂಸೆಗಳು.", "ಊಟ ಮುಗಿದ ನಂತರ.", "ಅದನ್ನು ಕ್ಷಮಿಸಲಾಗಿದೆ ಎಂದು ಹೇಳುವ ವ್ಯಕ್ತಿಯ ಹಿಂದಿನ ಪಾಪಗಳು."),
        "dua_host" to DuaText("ಆತಿಥೇಯರಿಗೆ", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ಅವರಿಗೆ ಏನು ಒದಗಿಸಿದ್ದೀಯೋ ಅದರಲ್ಲಿ ಅವರನ್ನು ಆಶೀರ್ವದಿಸ, ಅವರನ್ನು ಕ್ಷಮಿಸು ಮತ್ತು ಅವರ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸು.", "ಆತಿಥೇಯರಿಗೆ, ಯಾರೊಬ್ಬರ ಮನೆಯಲ್ಲಿ ಊಟ ಮಾಡಿದ ನಂತರ.", "ಸುನ್ನಾ ರೀತಿಯಲ್ಲಿ ಆತಿಥೇಯರಿಗೆ ಧನ್ಯವಾದಗಳು."),
        "dua_breaking_fast" to DuaText("ಉಪವಾಸವನ್ನು ಮುರಿದ ನಂತರ", "ಬಾಯಾರಿಕೆ ಹೋಗಿದೆ, ರಕ್ತನಾಳಗಳು ತೇವಗೊಂಡಿವೆ, ಮತ್ತು ಅಲ್ಲಾಹನ ಇಚ್ಛೆಯಿದ್ದರೆ ಪ್ರತಿಫಲವು ದೃಢವಾಗುತ್ತದೆ.", "ಇಫ್ತಾರ್ ಸಮಯದಲ್ಲಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಉಪವಾಸವನ್ನು ಮುರಿಯುವಾಗ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_new_clothes" to DuaText("ಹೊಸ ಬಟ್ಟೆಗಳನ್ನು ಧರಿಸಿ", "ಓ ಅಲ್ಲಾಹನೇ, ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ನಿನ್ನದೇ. ನೀನು ನನಗೆ ಇದನ್ನು ಧರಿಸಿದ್ದೀ. ಅದರ ಒಳ್ಳೆಯದನ್ನೂ, ಒಳ್ಳೆಯದನ್ನೂ, ಅದನ್ನು ಯಾವ ಉದ್ದೇಶಕ್ಕಾಗಿ ನಿರ್ಮಿಸಲಾಗಿತ್ತೋ ಅದನ್ನೂ ನಾನು ನಿನ್ನಲ್ಲಿ ಬೇಡಿಕೊಳ್ಳುತ್ತೇನೆ. ಅದರ ಕೆಟ್ಟದ್ದನ್ನೂ, ಕೆಟ್ಟದ್ದನ್ನೂ ಬಿಟ್ಟು ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಹೊಸ ಉಡುಪನ್ನು ಧರಿಸುವಾಗ (ಶರ್ಟ್ ಅಥವಾ ಪೇಟದಂತಹ).", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಹೊಸ ಉಡುಪನ್ನು ಧರಿಸುವಾಗ ಈ ದುಆವನ್ನು ಮಾಡಿದರು. (ಉಡುಪು ಧರಿಸಲು ದೈನಂದಿನ ದುಆ'ಬಟ್ಟೆ ಧರಿಸುವುದು'ಅಡಿಯಲ್ಲಿ ಇರುತ್ತದೆ.)"),
        "dua_rabbana_atina" to DuaText("ಈ ಲೋಕದಲ್ಲಿ ಮತ್ತು ಪರಲೋಕದಲ್ಲಿ ಒಳ್ಳೆಯದು.", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಮಗೆ ಈ ಲೋಕದಲ್ಲಿ ಒಳ್ಳೆಯದನ್ನು ಮತ್ತು ಪರಲೋಕದಲ್ಲಿ ಒಳ್ಳೆಯದನ್ನು ಕರುಣಿಸು ಮತ್ತು ನರಕದ ಶಿಕ್ಷೆಯಿಂದ ನಮ್ಮನ್ನು ರಕ್ಷಿಸು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಹೆಚ್ಚಾಗಿ ಮಾಡಿದ ದುಆ.", "ಈ ಲೋಕ ಮತ್ತು ಪರಕಾಲದ ಎಲ್ಲಾ ಒಳ್ಳೆಯದನ್ನು ಸಂಗ್ರಹಿಸುವ ದುಆ."),
        "dua_rabbi_zidni_ilma" to DuaText("ಜ್ಞಾನದಲ್ಲಿ ಹೆಚ್ಚಳ", "ನನ್ನ ಒಡೆಯನೇ, ನನಗೆ ಜ್ಞಾನವನ್ನು ಹೆಚ್ಚಿಸು.", "ಜ್ಞಾನದ ಹೆಚ್ಚಳಕ್ಕಾಗಿ.", "ಅಲ್ಲಾಹು ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರಿಗೆ ಜ್ಞಾನವನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೇನೂ ಹೆಚ್ಚಿಸಬಾರದೆಂದು ಆದೇಶಿಸಿದನು."),
        "dua_musa_sharh_sadr" to DuaText("ಎದೆಯ ತೆರೆಯುವಿಕೆ (ಮೂಸಾ ಎ. ಎಸ್)", "ನನ್ನ ಒಡೆಯನೇ, ನನಗಾಗಿ ನನ್ನ ಎದೆಯನ್ನು ವಿಸ್ತರಿಸು, ನನಗಾಗಿ ನನ್ನ ಕೆಲಸವನ್ನು ಸುಲಭಗೊಳಿಸು, ಮತ್ತು ನನ್ನ ನಾಲಿಗೆಯಿಂದ ಗಂಟುಗಳನ್ನು ಬಿಚ್ಚಿಕೊಳ್ಳಿ, ಇದರಿಂದ ಅವರು ನನ್ನ ಮಾತನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಬಹುದು.", "ಪರೀಕ್ಷೆಯ ಮೊದಲು, ಭಾಷಣ ಅಥವಾ ಯಾವುದೇ ಕಷ್ಟಕರವಾದ ಕೆಲಸ.", "ಪ್ರವಾದಿ ಮೂಸಾ (ಅ. ಸ.) ಅವರ ದುಆ-ಒಬ್ಬರ ಕೆಲಸದಲ್ಲಿ ಹೃದಯದ ಶಾಂತಿ ಮತ್ತು ಸುಲಭತೆ."),
        "dua_la_tuzigh" to DuaText("ಹೃದಯದ ಸ್ಥಿರತೆ", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನೀನು ನಮಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡಿದ ನಂತರ ನಮ್ಮ ಹೃದಯಗಳು ವಿಚಲಿತಗೊಳ್ಳದಿರಲಿ. ಮತ್ತು ನಮಗೆ ನಿನ್ನ ಕಡೆಯಿಂದ ಕರುಣೆಯನ್ನು ಕರುಣಿಸು. ನಿಶ್ಚಯವಾಗಿ ನೀನು ಅತ್ಯುತ್ತಮವಾದವನೂ ಆಗಿದ್ದೀ.", "ಮಾರ್ಗದರ್ಶನದ ಮೇಲೆ ಸ್ಥಿರತೆಗಾಗಿ.", "ನಂಬಿಕೆಯಲ್ಲಿ ದೃಢವಾಗಿ ಉಳಿಯಲು ಒಂದು ದುಆ."),
        "dua_ya_muqallib" to DuaText("ಓ ಟರ್ನರ್ ಆಫ್ ಹಾರ್ಟ್ಸ್", "ಓ ಹೃದಯದ ಟರ್ನರ್, ನನ್ನ ಹೃದಯವನ್ನು ನಿಮ್ಮ ಧರ್ಮದ ಮೇಲೆ ದೃಢವಾಗಿರಿಸಿಕೊಳ್ಳಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಆಗಾಗ್ಗೆ ಈ ದುಆವನ್ನು ಮಾಡುತ್ತಾರೆ.", "ಉಮ್ ಸಲಮಾ (ರ. ಅ.) ಪ್ರಕಾರ, ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಹೆಚ್ಚಾಗಿ ದುಆವನ್ನು ಮಾಡುತ್ತಾರೆ."),
        "dua_la_tuakhidhna" to DuaText("ಸೂರಾಹ್ ಅಲ್-ಬಖಾರಾ ಕೊನೆಯ ಪದ್ಯಗಳು", "ನಮ್ಮ ಒಡೆಯನೇ, ನಾವು ಮರೆತುಹೋದರೆ ಅಥವಾ ತಪ್ಪು ಮಾಡಿದರೆ, ನೀನು ನಮ್ಮ ಮೇಲೆ ದಂಡನೆ ಹೇರಬೇಡಿ. ನಮ್ಮ ಒಡೆಯನೇ, ನೀನು ನಮ್ಮ ಮೇಲೆ ನಮ್ಮ ಹಿಂದಿನವರ ಮೇಲೆ ಇಟ್ಟಂತಹ ಹೊರೆಯನ್ನು ಹೇರಬೇಡಿ. ನಮ್ಮ ಒಡೆಯನೇ, ನಾವು ಭರಿಸಲಾರದ ಹೊರೆಯನ್ನು ನಮ್ಮ ಮೇಲೆ ಹೊರಿಸಬೇಡ. ನಮ್ಮನ್ನು ಕ್ಷಮಿಸು, ಕ್ಷಮಿಸು ಮತ್ತು ನಮ್ಮ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸು. ನೀನು ನಮ್ಮ ರಕ್ಷಕನಾಗಿದ್ದೀ. ಆದ್ದರಿಂದ ಅವಿಶ್ವಾಸಿಗಳ ವಿರುದ್ಧ ನಮಗೆ ಸಹಾಯ ಮಾಡು.", "ಮಲಗುವ ಮೊದಲು ರಾತ್ರಿ-ಸೂರಹ್ ಅಲ್-ಬಕಾರಾದ ಕೊನೆಯ ಎರಡು ಶ್ಲೋಕಗಳು.", "ಸೂರಹ್ ಅಲ್-ಬಕಾರಾದ ಕೊನೆಯ ಎರಡು ಶ್ಲೋಕಗಳನ್ನು ರಾತ್ರಿಯಲ್ಲಿ ಯಾರು ಪಠಿಸುತ್ತಾರೋ, ಅವರು ಸಾಕು."),
        "dua_visiting_sick" to DuaText("ರೋಗಿಗಳಿಗೆ ಭೇಟಿ ನೀಡುವುದು", "ನಿಮ್ಮನ್ನು ಗುಣಪಡಿಸಲು ನಾನು ಪ್ರಬಲನಾದ, ಪ್ರಬಲ ಸಿಂಹಾಸನದ ಒಡೆಯನಾದ ಅಲ್ಲಾಹನನ್ನು ಕೇಳಿಕೊಳ್ಳುತ್ತೇನೆ.", "ಏಳು ಬಾರಿ ರೋಗಿಗಳನ್ನು ಭೇಟಿ ಮಾಡುವಾಗ.", "ಸಾವಿನ ಸಮಯ ಬರದಿದ್ದರೆ, ಅಲ್ಲಾಹು ಅವನನ್ನು ಗುಣಪಡಿಸುತ್ತಾನೆ."),
        "dua_ruqyah_pain" to DuaText("ದೈಹಿಕ ನೋವಿಗೆ", "ನಾನು ಏನು ಭಾವಿಸುತ್ತೇನೆ ಮತ್ತು ನಾನು ಏನು ಭಯ ಪಡುತ್ತೇನೆ ಎಂಬುದರ ದುಷ್ಟತನದಿಂದ ನಾನು ಅಲ್ಲಾಹನಲ್ಲಿ ಮತ್ತು ಅವನ ಶಕ್ತಿಯಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ನಿಮ್ಮ ಕೈಯನ್ನು ನೋವುಂಟುಮಾಡುವ ಸ್ಥಳದಲ್ಲಿ ಇರಿಸಿ, ಮೂರು ಬಾರಿ ಬಿಸ್ಮಿಲ್ಲಾಹ್ ಎಂದು ಹೇಳಿ, ನಂತರ ಈ ದುಆವನ್ನು ಏಳು ಬಾರಿ ಮಾಡಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಅದನ್ನು ಉಸ್ಮಾನ್ ಇಬ್ನ್ ಅಬಿಲ್ -'ಅಸ್ (ರ.) ಅವರಿಗೆ ನೋವುಗಾಗಿ ಕಲಿಸಿದರು."),
        "dua_ruqyah_nabawi" to DuaText("ರೋಗಿಗಳಿಗೆ ಪ್ರವಾದನಾತ್ಮಕ ರುಕ್ಯಾ", "ಓ ಅಲ್ಲಾಹನೇ, ಮನುಷ್ಯರ ಒಡೆಯನೇ! ಹಾನಿಯನ್ನು ತೆಗೆದುಹಾಕಿ ಮತ್ತು ಗುಣಪಡಿಸು, ಯಾಕೆಂದರೆ ನೀನೇ ಗುಣಪಡಿಸುವವನು; ನಿನ್ನ ಗುಣಪಡಿಸುವಿಕೆಯ ಹೊರತಾಗಿ ಯಾವುದೇ ಗುಣವಿಲ್ಲ-ಯಾವುದೇ ರೋಗವನ್ನು ಬಿಟ್ಟುಹೋಗದ ಗುಣ.", "ಅನಾರೋಗ್ಯದಿಂದ ಬಳಲುತ್ತಿರುವ ವ್ಯಕ್ತಿಯ ಮೇಲೆ ಕೈ ಹಾಕುವಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ತಮ್ಮ ಕುಟುಂಬದ ಅನಾರೋಗ್ಯದ ಸದಸ್ಯರನ್ನು ಭೇಟಿ ಮಾಡುವಾಗ ಇದನ್ನು ಪಠಿಸಿದರು."),
        "dua_kalimat_tammat" to DuaText("ಪರಿಪೂರ್ಣ ಪದಗಳಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಹುಡುಕುವುದು", "ನಾನು ಅಲ್ಲಾಹನ ಪರಿಪೂರ್ಣ ಮಾತುಗಳಲ್ಲಿ ಆತನು ಸೃಷ್ಟಿಸಿರುವ ದುಷ್ಟತನದಿಂದ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಒಂದು ಸ್ಥಳದಲ್ಲಿ ಅಥವಾ ಸಂಜೆ ನಿಲ್ಲುವಾಗ.", "ಯಾರೇ ಒಂದು ಸ್ಥಳದಲ್ಲಿ ನಿಲ್ಲಿಸಿ ಇದನ್ನು ಹೇಳುತ್ತಾರೋ, ಅವನು ಅದನ್ನು ಬಿಟ್ಟು ಹೋಗುವವರೆಗೆ ಅವನಿಗೆ ಏನೂ ಹಾನಿಯಾಗುವುದಿಲ್ಲ."),
        "dua_evil_eye" to DuaText("ಮಕ್ಕಳ ರಕ್ಷಣೆ (ದುಷ್ಟ ಕಣ್ಣು)", "ನಾನು ನಿಮ್ಮಿಬ್ಬರಿಗೂ, ಪ್ರತಿಯೊಂದು ದೆವ್ವ ಮತ್ತು ಪ್ರತಿಯೊಂದು ವಿಷಕಾರಿ ಪ್ರಾಣಿಯಿಂದ ಮತ್ತು ಪ್ರತಿಯೊಂದು ಹಾನಿಕಾರಕ ಕಣ್ಣಿನಿಂದ, ಅಲ್ಲಾಹುವಿನ ಪರಿಪೂರ್ಣ ಮಾತುಗಳಲ್ಲಿ ರಕ್ಷಣೆಯನ್ನು ಕೋರುತ್ತೇನೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರು ಇದನ್ನು ಹಸನ್ ಮತ್ತು ಹುಸೇನ್ (ರ.) ಅವರ ಮೇಲೆ ಪಠಿಸಿದರು.", "ಮಕ್ಕಳನ್ನು ದುಷ್ಟ ಕಣ್ಣು ಮತ್ತು ಹಾನಿಯಿಂದ ರಕ್ಷಿಸಲು ಸುನ್ನಹ್ ದುಆ (ಒಂದು ಮಗುವಿಗೆ'ಉಧುಕಾ'ಎಂದು ಹೇಳಲಾಗುತ್ತದೆ)."),
        "dua_seeing_afflicted" to DuaText("ಯಾರನ್ನಾದರೂ ವಿಚಾರಣೆಗೊಳಪಡಿಸುತ್ತಿರುವುದನ್ನು ನೋಡುವುದು", "ನಿಮ್ಮನ್ನು ಪರೀಕ್ಷಿಸಿದ ಸಂಗತಿಗಳಿಂದ ನನ್ನನ್ನು ರಕ್ಷಿಸಿದ ಮತ್ತು ತನ್ನ ಸೃಷ್ಟಿಯ ಬಹುಪಾಲು ಭಾಗಕ್ಕಿಂತ ನನಗೆ ಅನುಗ್ರಹ ನೀಡಿದ ಅಲ್ಲಾಹನಿಗಾಗಿ ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಇದೆ.", "ಯಾರನ್ನಾದರೂ ವಿಚಾರಣೆಯಲ್ಲಿ ನೋಡಿದಾಗ (ಅದನ್ನು ನಿಮಗೆ ನೀವೇ ಮೌನವಾಗಿ ಹೇಳಿ).", "ಅದನ್ನು ಆ ವಿಚಾರಣೆಯಿಂದ ಸುರಕ್ಷಿತವಾಗಿಡಲಾಗಿದೆ ಎಂದು ಹೇಳುವವರು."),
        "dua_istikhara" to DuaText("ಸಲಾತ್ ಅಲ್-ಇಸ್ತಿಕಾರಾ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನ ಜ್ಞಾನದ ಮೂಲಕ ಒಳ್ಳೆಯದನ್ನು ಹುಡುಕುತ್ತೇನೆ, ನಿನ್ನ ಶಕ್ತಿಯ ಮೂಲಕ ಸಾಮರ್ಥ್ಯವನ್ನು ಹುಡುಕುತ್ತೇನೆ, ಮತ್ತು ನಿನ್ನ ದೊಡ್ಡ ಅನುಗ್ರಹವನ್ನು ನಾನು ನಿನ್ನನ್ನು ಕೇಳುತ್ತೇನೆ. ನಿನಗೆ ಅಧಿಕಾರವಿದೆ ಮತ್ತು ನನಗೆ ಯಾವುದೇ ಇಲ್ಲ. ನಿನಗೆ ತಿಳಿದಿದೆ ಮತ್ತು ನಾನು ತಿಳಿದಿಲ್ಲ, ಮತ್ತು ನೀನು ಅದೃಶ್ಯವನ್ನು ಬಲ್ಲವನಾಗಿದ್ದೀ. ಓ ಅಲ್ಲಾಹನೇ, ನಿನಗೆ ತಿಳಿದಿರುವ ಈ ವಿಷಯವು (ನನ್ನ ಧರ್ಮ, ನನ್ನ ಜೀವನ ಮತ್ತು ನನ್ನ ಅಂತ್ಯಕ್ಕೆ ಒಳ್ಳೆಯದು) ಆಗಿದ್ದರೆ, ನನಗೆ ಅದನ್ನು ಆದೇಶಿಸು, ನನಗೆ ಅದನ್ನು ಸುಲಭಗೊಳಿಸು ಮತ್ತು ಅದರಲ್ಲಿ ನನಗೆ ಆಶೀರ್ವಾದ ಕೊಡು. ಮತ್ತು ನಿನಗೆ ತಿಳಿದಿರುವ ಈ ವಿಷಯವು ನನ್ನ ಧರ್ಮ, ನನ್ನ ಜೀವನ ಮತ್ತು ನನ್ನ ಅಂತ್ಯಕ್ಕೆ ಕೆಟ್ಟದಾಗಿದ್ದರೆ, ಅದನ್ನು ನನ್ನಿಂದ ದೂರವಿರಿಸು ಮತ್ತು ಅದರಿಂದ ನನ್ನನ್ನು ದೂರ ತಿರುಗಿಸು, ಮತ್ತು ಅದು ಎಲ್ಲಿದ್ದರೂ ನನಗೆ ಒಳ್ಳೆಯದನ್ನು ಆದೇಶಿಸು, ನಂತರ ಅದರಿಂದ ನನ್ನನ್ನು ತೃಪ್ತಿಪಡಿಸು.", "ಸ್ವಯಂಪ್ರೇರಿತ ಪ್ರಾರ್ಥನೆಯ ಎರಡು ರಕಾಠಿಗಳ ನಂತರ, ಅನುಮತಿಸಲಾದ ವಿಷಯದಲ್ಲಿ ಯಾವುದು ಉತ್ತಮವಾದುದು ಎಂಬುದನ್ನು ಹುಡುಕುವುದು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಕುರಾನ್ನ ಸೂರಾವನ್ನು ಕಲಿಸಿದಂತೆ ಎಲ್ಲಾ ವಿಷಯಗಳಲ್ಲಿ ಸಹಚರರಿಗೆ ಇಸ್ತಿಕಾರಾ ಕಲಿಸಿದರು."),
    )
}
